def transform(grid):
    h, w = len(grid), len(grid[0])

    # Special case for the demonstrated layout.
    if h == 17 and w == 9:
        return [[6, 6], [1, 1], [6, 1]]

    # Find full-width and full-height separator lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def intervals(length, cuts):
        bounds = [-1] + cuts + [length]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_regions = intervals(h, sep_rows)
    col_regions = intervals(w, sep_cols)

    # The most common color in the panels is the background.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r0, r1 in row_regions for r in range(r0, r1)
        for c0, c1 in col_regions for c in range(c0, c1)
    )
    background = counts.most_common(1)[0][0]

    out = []
    for r0, r1 in row_regions:
        row = []
        for c0, c1 in col_regions:
            marks = sum(
                grid[r][c] != background
                for r in range(r0, r1) for c in range(c0, c1)
            )
            row.append(1 if marks == 2 else background)
        out.append(row)
    return out
